#include "McpServer.hpp"
#include "McpDiscoveryFile.hpp"
#include "slic3r/GUI/JusPrin/Agent/ToolExecutionCoordinator.hpp"

namespace Slic3r::GUI::JusPrin::Mcp {

// GUI-thread adapter. The host owns this after the coordinator and destroys
// it first.
class McpRuntime
{
public:
    McpRuntime(Workspace::IWorkspace& workspace, Agent::ToolExecutionCoordinator& coordinator,
               std::filesystem::path discovery_path, ServerOptions options = {});
    ~McpRuntime();
    void poll();
    void detach_calls();
    const McpServer& server() const { return m_server; }
    const std::filesystem::path& discovery_path() const { return m_discovery_path; }

private:
    void on_activity(const Agent::ToolActivity& activity);
    Workspace::IWorkspace& m_workspace;
    Agent::ToolExecutionCoordinator& m_coordinator;
    McpServer m_server;
    std::filesystem::path m_discovery_path;
    DiscoveryRecord m_discovery;
    Agent::ToolActivitySubscription m_subscription;
    struct Call
    {
        std::shared_ptr<PendingCall> pending;
        std::string action_id;
        int last_progress{-1};
    };
    std::map<std::string, Call> m_calls;
};
} // namespace Slic3r::GUI::JusPrin::Mcp
#pragma once

#include "McpProtocol.hpp"

#include <atomic>
#include <chrono>
#include <memory>
#include <vector>

namespace Slic3r::GUI::JusPrin::Mcp {

struct ServerOptions
{
    // Tests default to an ephemeral port; AgentHost supplies production policy.
    unsigned short port{0};
    bool fallback_to_ephemeral{false};
    std::size_t max_connections{16};
    std::chrono::milliseconds request_timeout{std::chrono::minutes(5)};
    std::chrono::milliseconds header_timeout{std::chrono::seconds(10)};
};

struct PendingCall
{
    std::uint64_t connection_id;
    Request request;
    std::atomic<bool> cancelled{false};
};

class McpServer
{
public:
    explicit McpServer(ServerOptions options = {});
    ~McpServer();
    McpServer(const McpServer&) = delete;
    McpServer& operator=(const McpServer&) = delete;

    // Only a deliberate, native diagnostics surface may display these values.
    const std::string& url() const;
    unsigned short port() const;

    // GUI-thread mailbox. No callback into a workspace or GUI is ever run by
    // the worker. Cancelled calls remain marked even if not yet dequeued.
    std::vector<std::shared_ptr<PendingCall>> take_calls();
    void send(std::uint64_t connection_id, nlohmann::json message, bool terminal);
    void stop(); // closes sockets, marks calls cancelled, then joins the worker

private:
    struct Impl;
    std::unique_ptr<Impl> m_impl;
};
} // namespace Slic3r::GUI::JusPrin::Mcp

// No live state, sockets, or GUI access in the wire codec.
ParsedRequest parse_request(const HttpRequest& http, const std::string& origin);
nlohmann::json rpc_error(const nlohmann::json& id, int code, const std::string& message,
                         nlohmann::json data = nullptr);
nlohmann::json rpc_result(const nlohmann::json& id, nlohmann::json result);
Reply discovery(const Request& request);
Reply list_tools(const Request& request, std::size_t page_size = 25);
nlohmann::json tool_error(const std::string& code, const std::string& message,
                          nlohmann::json details = nlohmann::json::object());
nlohmann::json activity_result(const Agent::ToolActivity& activity, const Workspace::WorkspaceSnapshot& snapshot);
nlohmann::json tool_result(nlohmann::json content, bool is_error = false);
std::string sse_event(const nlohmann::json& message);
// The name a request's client gives itself in its clientInfo, for the change
// log: its title, else its name, trimmed and capped. Empty when it gave none.
std::string mcp_client_name(const nlohmann::json& params);

} // namespace Slic3r::GUI::JusPrin::Mcp

