  flex-direction: column;
  gap: 16px;
  margin-bottom: 8px;
}

.agent-card {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  padding: 16px;
  background: var(--surface-subtle);
  border-radius: var(--radius-medium);
  box-shadow: inset 0 0 0 1px var(--border-subtle);
}

/* The own-account card, smaller in the narrow column (board first-run-10). */
.agent-card .onboarding-door {
  padding: 8px 12px;
}

.agent-card .onboarding-door-name {
  font: var(--font-body-small-bold);
}

.agent-card .onboarding-door-title,
.agent-card .sign-in-title {
  font: var(--font-body-bold);
}

.agent-card .button-primary {
  justify-content: center;
}

/* The sign-in door's paragraphs, which the welcome's .onboarding reset
   does not reach here; the card's gap spaces them. */
.agent-card p {
  margin: 0;
}

/* The column is too narrow for a field beside its button: the button goes
   under the field, each the card's width. */
.agent-card .sign-in-email-row {
  flex-direction: column;
}

/* Six full-size code cells are wider than the column: they share its width
   and stay square. */
.agent-card .code-cell {
  flex: 1 1 0;
  width: auto;
  height: auto;
  aspect-ratio: 1;
}

/* The links wrap here; without the dots a wrapped line does not start with one. */
.agent-card .sign-in-links {
  column-gap: 12px;
}

.agent-card .sign-in-link-dot {
  display: none;
}

/* A spent code's "Send a new code" takes the card's width, its links under it. */
.agent-card .sign-in-new-code-row {
  flex-direction: column;
  align-items: stretch;
}

.agent-card-heading {
  font: var(--font-body-bold);
}

.agent-card-why {
  font: var(--font-body-small);
  color: var(--text-secondary);
}

.agent-card-head {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.agent-card-head .glyph-connected {
  margin-top: 4px;
  background: var(--status-success);
}

.agent-card-title {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  font: var(--font-label);
